package bo.edu.uagrm.saludu.agenda.api; import bo.edu.uagrm.saludu.identity.infrastructure.SessionPrincipal; import bo.edu.uagrm.saludu.shared.persistence.*; import java.util.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/appointments") public class AppointmentAttendanceController {private final JdbcTemplate j;private final DatabaseActorContext c;public AppointmentAttendanceController(JdbcTemplate j,DatabaseActorContext c){this.j=j;this.c=c;}private void x(SessionPrincipal p){c.apply(new DatabaseActor(p.id(),Set.copyOf(p.roles())));}@PostMapping("/{id}/check-in") @PreAuthorize("hasRole('ADMINISTRATIVE')") @Transactional public LegacyAvailabilityResponse<Void> checkIn(@PathVariable UUID id,@AuthenticationPrincipal SessionPrincipal p){x(p);j.query("select salud_u.registrar_llegada_cita(?)",r->{},id);return LegacyAvailabilityResponse.success(null);}@PostMapping("/{id}/no-show") @PreAuthorize("hasRole('ADMINISTRATIVE')") @Transactional public LegacyAvailabilityResponse<Void> noShow(@PathVariable UUID id,@RequestBody(required=false) Map<String,Object>b,@AuthenticationPrincipal SessionPrincipal p){x(p);j.query("select salud_u.registrar_ausencia_cita(?,?)",r->{},id,b==null?null:b.get("reason"));return LegacyAvailabilityResponse.success(null);}}
